#define CRC32C7X3X8(ITR) do {\
        CRC32C3X8((ITR)*7+0) \
        CRC32C3X8((ITR)*7+1) \
        CRC32C3X8((ITR)*7+2) \
        CRC32C3X8((ITR)*7+3) \
        CRC32C3X8((ITR)*7+4) \
        CRC32C3X8((ITR)*7+5) \
        CRC32C3X8((ITR)*7+6) \
        } while(0)

